"use client";

import { useMemo, useState } from "react";
import { AdminHeader } from "@/components/admin/AdminHeader";
import { useLocalStorageState } from "@/lib/useLocalStorageState";
import { applications } from "@/lib/data/applications";
import { StatusBadge } from "@/components/shared/StatusBadge";
import { companies, drives } from "@/lib/data/companies";
import { students } from "@/lib/data/students";
import { APPLICATION_JOURNEY, formatDate } from "@/lib/utils";
import type { ApplicationStatus } from "@/lib/types";
import {
  Activity, Building2, CalendarDays, CheckCircle2, ClipboardCheck, Download,
  FileSpreadsheet, Mail, Plus, Search, ShieldCheck, SlidersHorizontal, Users,
} from "lucide-react";

const panels = ["Command center", "Candidate ATS", "Employer CRM", "Policies & eligibility", "Interviews & drive day", "Assessments & offers", "Drive analyzer", "Reports & data", "Communications & audit", "Employer discovery", "TPO insight assistant"] as const;
type Panel = (typeof panels)[number];
type Contact = { id: string; company: string; name: string; email: string; nextFollowUp: string; notes: string[] };
type Interview = { id: string; candidate: string; company: string; round: string; date: string; time: string; room: string };
type Assessment = { id: string; title: string; type: string; duration: number; questions: number; status: "Draft" | "Published" };
type Offer = { id: string; student: string; company: string; role: string; packageLPA: number; status: "Draft" | "Released" | "Viewed" | "Accepted" | "Rejected" | "Joined"; deadline: string };
type OpsData = {
  contacts: Contact[]; interviews: Interview[]; checkedIn: string[]; assessments: Assessment[]; offers: Offer[];
  policies: { maxAppsPerDay: number; noActiveBacklogs: boolean; blockAfterPlacement: boolean; dreamThresholdLPA: number };
  importRows: { name: string; rollNumber: string; email: string; branch: string; cgpa: string }[];
  communications: { title: string; audience: string; date: string }[]; audit: { action: string; at: string }[];
};
const initialOps: OpsData = {
  contacts: companies.slice(0, 3).map((company, index) => ({ id: `contact-${company.id}`, company: company.name, name: ["Campus Talent Team", "University Relations", "Recruiting Partner"][index], email: `campus.${company.name.toLowerCase().replaceAll(" ", "")}@example.com`, nextFollowUp: "2026-10-08", notes: ["Previous campus drive tracked in placement records"] })),
  interviews: [], checkedIn: [], assessments: [], offers: [
    { id: "offer-demo", student: "Aman Verma", company: "Amazon", role: "SDE-1 (Backend)", packageLPA: 38, status: "Released", deadline: "2026-10-05" },
  ],
  policies: { maxAppsPerDay: 3, noActiveBacklogs: true, blockAfterPlacement: true, dreamThresholdLPA: 15 },
  importRows: [], communications: [], audit: [],
};

function csvDownload(filename: string, rows: string[][]) {
  const csv = rows.map((row) => row.map((value) => `"${String(value).replaceAll('"', '""')}"`).join(",")).join("\r\n");
  const link = document.createElement("a");
  link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  link.download = filename;
  link.click();
  URL.revokeObjectURL(link.href);
}

export default function AdminOperationsPage() {
  const [panel, setPanel] = useState<Panel>("Command center");
  const [data, setData, ready] = useLocalStorageState<OpsData>("placement-helper:tpo-operations", initialOps);
  const [stageOverrides, setStageOverrides] = useLocalStorageState<Record<string, ApplicationStatus>>("placement-helper:application-stages", {});
  const [contactForm, setContactForm] = useState({ company: companies[0].name, name: "", email: "", nextFollowUp: "2026-10-08" });
  const [interaction, setInteraction] = useState<Record<string, string>>({});
  const [interviewForm, setInterviewForm] = useState({ candidate: students[0].name, company: companies[0].name, round: "Technical round", date: "2026-10-06", time: "10:00", room: "Room 1" });
  const [interviewError, setInterviewError] = useState("");
  const [assessmentForm, setAssessmentForm] = useState({ title: "", type: "Technical MCQ", duration: 45, questions: 20 });
  const [broadcastForm, setBroadcastForm] = useState({ title: "", audience: "All final-year students" });
  const [fileError, setFileError] = useState("");
  const [filter, setFilter] = useState("");
  const [copilotPrompt, setCopilotPrompt] = useState("");
  const [copilotAnswer, setCopilotAnswer] = useState("");
  const [analysisDriveId, setAnalysisDriveId] = useState(drives[0]?.id ?? "");
  const [policyCheck, setPolicyCheck] = useState({ cgpa: "8.0", backlogs: "0", placed: false, appsToday: "0", package: "" });

  const effectiveApplications = applications.map((application) => ({ ...application, status: stageOverrides[application.id] ?? application.status }));
  const pending = effectiveApplications.filter((application) => application.status === "Not Responded").length;
  const studentApps = applications.length;
  const scheduledInterviews = data.interviews.length;
  const scheduledForDay = useMemo(() => data.interviews.filter((interview) => interview.date === new Date().toISOString().slice(0, 10)).length, [data.interviews]);

  function record(action: string) {
    setData((current) => ({ ...current, audit: [{ action, at: new Date().toISOString() }, ...current.audit].slice(0, 100) }));
  }
  function addContact(event: React.FormEvent) {
    event.preventDefault();
    if (!contactForm.name.trim() || !contactForm.email.includes("@")) return;
    setData((current) => ({ ...current, contacts: [{ ...contactForm, id: crypto.randomUUID(), notes: [] }, ...current.contacts] }));
    record(`Added CRM contact for ${contactForm.company}`);
    setContactForm({ ...contactForm, name: "", email: "" });
  }
  function addInterview(event: React.FormEvent) {
    event.preventDefault();
    const conflict = data.interviews.some((item) => item.date === interviewForm.date && item.time === interviewForm.time && item.room.toLowerCase() === interviewForm.room.toLowerCase());
    if (conflict) { setInterviewError("That room already has an interview at this time. Choose another slot or room."); return; }
    setData((current) => ({ ...current, interviews: [{ ...interviewForm, id: crypto.randomUUID() }, ...current.interviews] }));
    setInterviewError("");
    record(`Scheduled ${interviewForm.round} for ${interviewForm.candidate}`);
  }
  function createAssessment(event: React.FormEvent) {
    event.preventDefault();
    if (!assessmentForm.title.trim()) return;
    setData((current) => ({ ...current, assessments: [{ ...assessmentForm, id: crypto.randomUUID(), status: "Draft" }, ...current.assessments] }));
    record(`Created assessment draft: ${assessmentForm.title}`);
    setAssessmentForm({ title: "", type: "Technical MCQ", duration: 45, questions: 20 });
  }
  function updateOffer(offerId: string, status: Offer["status"]) {
    setData((current) => ({ ...current, offers: current.offers.map((offer) => offer.id === offerId ? { ...offer, status } : offer) }));
    record(`Moved offer ${offerId} to ${status}`);
  }
  function sendBroadcast(event: React.FormEvent) {
    event.preventDefault();
    if (!broadcastForm.title.trim()) return;
    setData((current) => ({ ...current, communications: [{ ...broadcastForm, date: new Date().toISOString() }, ...current.communications] }));
    record(`Saved announcement draft: ${broadcastForm.title}`);
    setBroadcastForm({ ...broadcastForm, title: "" });
  }
  async function importStudents(file?: File) {
    if (!file) return;
    setFileError("");
    const lines = (await file.text()).split(/\r?\n/).filter(Boolean);
    const headers = lines.shift()?.split(",").map((part) => part.trim().toLowerCase().replaceAll(/^"|"$/g, "")) ?? [];
    const required = ["name", "rollnumber", "email", "branch", "cgpa"];
    if (required.some((header) => !headers.includes(header))) { setFileError("CSV needs headers: name, rollNumber, email, branch, cgpa."); return; }
    const at = (name: string) => headers.indexOf(name);
    const parsed = lines.map((line) => line.split(",").map((part) => part.trim().replaceAll(/^"|"$/g, ""))).map((row) => ({ name: row[at("name")] ?? "", rollNumber: row[at("rollnumber")] ?? "", email: row[at("email")] ?? "", branch: row[at("branch")] ?? "", cgpa: row[at("cgpa")] ?? "" }));
    const valid = parsed.filter((row) => row.name && row.rollNumber && row.email.includes("@") && !Number.isNaN(Number(row.cgpa)));
    const invalid = parsed.length - valid.length;
    setData((current) => ({ ...current, importRows: [...valid, ...current.importRows] }));
    record(`Imported ${valid.length} student rows${invalid ? `; rejected ${invalid} invalid rows` : ""}`);
    setFileError(`${valid.length} rows accepted${invalid ? ` · ${invalid} rows need correction` : ""}. Imported rows stay in this browser only.`);
  }

  const eligibleStudents = students.filter((student) => student.branch === "CSE" && student.cgpa >= 8 && student.backlogs === 0);
  const blocked = Number(policyCheck.cgpa) < 6 || (data.policies.noActiveBacklogs && Number(policyCheck.backlogs) > 0) || (data.policies.blockAfterPlacement && policyCheck.placed) || Number(policyCheck.appsToday) >= data.policies.maxAppsPerDay || (policyCheck.package && Number(policyCheck.package) < data.policies.dreamThresholdLPA);

  function askTpoAssistant() {
    const query = copilotPrompt.toLowerCase();
    if (query.includes("eligible") || query.includes("cgpa")) {
      const matches = eligibleStudents.filter((student) => student.branch === "CSE" && student.cgpa >= 8 && student.backlogs === 0);
      setCopilotAnswer(`From the seeded student list, ${matches.length} CSE students have CGPA ≥ 8.0 and no backlogs: ${matches.map((student) => `${student.name} (${student.rollNumber}, ${student.cgpa})`).join(", ")}. This is a local sample query; select a specific drive for its full eligibility rules.`);
    } else if (query.includes("confirm") || query.includes("participat")) {
      const waiting = effectiveApplications.filter((application) => application.status === "Not Responded");
      setCopilotAnswer(`${waiting.length} sample application records are marked Not Responded: ${waiting.map((application) => `${application.studentName} — ${application.companyName}`).join(", ") || "none"}. Review the candidate ATS before sending any follow-up.`);
    } else if (query.includes("drop") || query.includes("conversion") || query.includes("drive")) {
      const buckets = ["Confirmed", "Shortlisted", "Assessment", "Interview", "Selected", "Placed"];
      const summary = buckets.map((status) => `${status}: ${effectiveApplications.filter((application) => application.status === status).length}`).join(" · ");
      setCopilotAnswer(`Current sample pipeline counts: ${summary}. These counts reflect loaded records and local status updates; they do not include external ATS data or establish why candidates dropped off.`);
    } else if (query.includes("email") || query.includes("recruiter")) {
      setCopilotAnswer("I can prepare wording for a recruiter follow-up, but this local preview cannot send it. Suggested draft: “Hello, I’m following up on the campus hiring process and would be happy to coordinate the next steps. Please let us know your preferred dates and candidate requirements.” Review it in Communications & audit before copying.");
    } else {
      setCopilotAnswer("Try a question about CSE eligibility, pending confirmations, drive funnel counts, or a recruiter follow-up. Answers use the sample data and simple local rules; no AI model or live institutional data is connected.");
    }
  }

  return (
    <div>
      <AdminHeader title="Placement operations" subtitle="Coordinate the hiring lifecycle with a local, interactive workspace" />
      <div className="mx-auto max-w-7xl space-y-6 p-5 sm:p-7">
        <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          {[
            { label: "Student records", value: students.length + data.importRows.length, icon: Users, sub: "Sample + browser imports" },
            { label: "Applications", value: studentApps, icon: ClipboardCheck, sub: `${pending} pending confirmations` },
            { label: "Scheduled interviews", value: scheduledInterviews, icon: CalendarDays, sub: `${scheduledForDay} today` },
            { label: "Employer contacts", value: data.contacts.length, icon: Building2, sub: "Follow-ups tracked locally" },
          ].map((item) => <div key={item.label} className="rounded-xl border border-slate-200 bg-white p-4"><div className="flex items-center justify-between"><p className="text-xs font-medium text-slate-500">{item.label}</p><item.icon className="h-4 w-4 text-indigo-500"/></div><p className="mt-2 text-2xl font-bold text-slate-950">{item.value}</p><p className="mt-1 text-[10px] text-slate-400">{item.sub}</p></div>)}
        </section>
        <div className="flex gap-2 overflow-x-auto pb-1" role="tablist" aria-label="Placement office modules">{panels.map((item) => <button key={item} role="tab" aria-selected={panel === item} onClick={() => setPanel(item)} className={`shrink-0 rounded-lg px-3.5 py-2 text-xs font-semibold ${panel === item ? "bg-slate-900 text-white" : "border border-slate-200 bg-white text-slate-600 hover:bg-slate-50"}`}>{item}</button>)}</div>

        {panel === "Command center" && <section className="grid gap-5 xl:grid-cols-[1.2fr_0.8fr]"><div className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-center gap-2"><Activity className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Placement control center</h3></div><p className="mt-1 text-xs text-slate-500">Prioritize the next actions across active placement activity.</p><div className="mt-5 space-y-3">{[
          { title: `${pending} students need follow-up`, detail: "Open the follow-up queue to review students who have not confirmed participation.", href: "/admin/followups", action: "Review queue" },
          { title: `${scheduledInterviews} interviews scheduled`, detail: "Check room conflicts and review the calendar for upcoming rounds.", href: "#", action: "Schedule interview", target: "Interviews & drive day" },
          { title: `${drives.length} placement drives on record`, detail: "Update deadlines, stages, and eligibility criteria in the drive manager.", href: "/admin/drives", action: "Manage drives" },
          { title: `${eligibleStudents.length} sample students match CSE · CGPA 8+ · zero backlog`, detail: "Eligibility is computed from the currently loaded sample student records.", href: "/admin/students", action: "View students" },
        ].map((item) => <div key={item.title} className="flex flex-col gap-3 rounded-xl border border-slate-100 p-4 sm:flex-row sm:items-center"><div className="flex-1"><p className="text-sm font-semibold text-slate-800">{item.title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{item.detail}</p></div>{item.target ? <button onClick={() => setPanel(item.target as Panel)} className="rounded-lg bg-slate-900 px-3 py-2 text-[10px] font-semibold text-white">{item.action}</button> : <a href={item.href} className="rounded-lg bg-slate-900 px-3 py-2 text-center text-[10px] font-semibold text-white">{item.action}</a>}</div>)}</div></div><div className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><h3 className="font-bold text-slate-900">Placement journey</h3><p className="mt-1 text-xs text-slate-500">Sample pipeline totals from seeded applications and local stage updates</p><div className="mt-5 space-y-3">{["Not Responded", "Confirmed", "Shortlisted", "Assessment", "Interview", "Selected", "Placed"].map((status) => { const count = effectiveApplications.filter((application) => application.status === status).length; return <div key={status} className="flex items-center gap-3"><span className="w-24 text-xs text-slate-600">{status}</span><div className="h-2 flex-1 rounded-full bg-slate-100"><div className="h-2 rounded-full bg-indigo-500" style={{ width: `${Math.max(count / Math.max(effectiveApplications.length, 1) * 100, count ? 8 : 0)}%` }}/></div><b className="w-6 text-right text-xs text-slate-800">{count}</b></div>; })}</div><p className="mt-4 text-[10px] text-slate-400">These are demo records; totals are not live institutional analytics.</p></div></section>}

        {panel === "Candidate ATS" && <section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><div className="flex items-center gap-2"><Users className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Candidate pipeline</h3></div><p className="mt-1 text-xs text-slate-500">Update candidate stages and see the same stage in the student tracker. Changes are stored in this browser.</p></div><label className="relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400"/><input value={filter} onChange={(event) => setFilter(event.target.value)} placeholder="Search name, roll no, company" className="rounded-lg border border-slate-200 py-2 pl-9 pr-3 text-xs"/></label></div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[800px] text-left"><thead><tr className="border-b border-slate-100 text-[10px] uppercase tracking-wide text-slate-400"><th className="p-3">Student</th><th className="p-3">Company / role</th><th className="p-3">Eligibility</th><th className="p-3">Stage</th><th className="p-3">Update stage</th></tr></thead><tbody className="divide-y divide-slate-50">{applications.filter((application) => `${application.studentName} ${application.studentRollNumber} ${application.companyName}`.toLowerCase().includes(filter.toLowerCase())).map((application) => { const current = stageOverrides[application.id] ?? application.status; const drive = drives.find((item) => item.id === application.driveId); return <tr key={application.id} className="text-xs"><td className="p-3"><b className="text-slate-800">{application.studentName}</b><p className="mt-1 text-[10px] text-slate-400">{application.studentRollNumber} · {application.studentBranch}</p></td><td className="p-3 text-slate-700">{application.companyName}<p className="mt-1 text-[10px] text-slate-400">{application.driveName}</p></td><td className="p-3">{drive ? <span className={application.studentBranch === "CSE" && drive.eligibility.branches.includes(application.studentBranch) ? "text-emerald-700" : "text-amber-700"}>{drive.eligibility.branches.includes(application.studentBranch) ? "Branch listed" : "Branch mismatch"}</span> : "Pending"}</td><td className="p-3"><StatusBadge status={current} size="sm"/></td><td className="p-3"><select value={current} onChange={(event) => { const next = event.target.value as ApplicationStatus; setStageOverrides((currentStages) => ({ ...currentStages, [application.id]: next })); record(`Moved ${application.studentName} at ${application.companyName} to ${next}`); }} className="rounded-lg border border-slate-200 bg-white px-2 py-1.5 text-xs"><option value="Not Responded">Not Responded</option>{APPLICATION_JOURNEY.map((stage) => <option key={stage} value={stage}>{stage}</option>)}<option value="Rejected">Rejected</option></select></td></tr>; })}</tbody></table>{applications.filter((application) => `${application.studentName} ${application.studentRollNumber} ${application.companyName}`.toLowerCase().includes(filter.toLowerCase())).length === 0 && <p className="py-12 text-center text-sm text-slate-500">No candidates match your search.</p>}</div></section>}

        {panel === "Employer CRM" && <section className="grid gap-5 xl:grid-cols-[0.8fr_1.2fr]"><div className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="font-bold text-slate-900">Add recruiter relationship</h3><p className="mt-1 text-xs text-slate-500">Contact details and follow-up notes stay in this browser.</p><form onSubmit={addContact} className="mt-4 space-y-3"><label className="block text-xs font-medium text-slate-600">Company<select value={contactForm.company} onChange={(event) => setContactForm({ ...contactForm, company: event.target.value })} className="mt-1 w-full rounded-lg border border-slate-200 p-2.5 text-sm">{companies.map((company) => <option key={company.id}>{company.name}</option>)}</select></label><input required placeholder="Recruiter name" value={contactForm.name} onChange={(event) => setContactForm({ ...contactForm, name: event.target.value })} className="w-full rounded-lg border border-slate-200 p-2.5 text-sm"/><input required type="email" placeholder="Work email" value={contactForm.email} onChange={(event) => setContactForm({ ...contactForm, email: event.target.value })} className="w-full rounded-lg border border-slate-200 p-2.5 text-sm"/><label className="block text-xs text-slate-600">Next follow-up<input type="date" value={contactForm.nextFollowUp} onChange={(event) => setContactForm({ ...contactForm, nextFollowUp: event.target.value })} className="mt-1 w-full rounded-lg border border-slate-200 p-2.5 text-sm"/></label><button className="inline-flex items-center gap-2 rounded-lg bg-slate-900 px-4 py-2.5 text-xs font-semibold text-white"><Plus className="h-3.5 w-3.5"/>Add contact</button></form></div><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between"><div><h3 className="font-bold text-slate-900">Employer relationships</h3><p className="mt-1 text-xs text-slate-500">Record follow-ups, hiring history, and recruiter next steps.</p></div><span className="rounded-full bg-indigo-50 px-2.5 py-1 text-[10px] font-semibold text-indigo-700">{data.contacts.length} contacts</span></div><div className="mt-4 space-y-3">{data.contacts.map((contact) => <article key={contact.id} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><h4 className="text-sm font-semibold text-slate-900">{contact.name}</h4><p className="text-xs text-slate-500">{contact.company} · {contact.email}</p></div><span className="rounded-lg bg-amber-50 px-2 py-1 text-[10px] text-amber-800">Follow up {formatDate(contact.nextFollowUp)}</span></div><p className="mt-2 text-xs text-slate-500">Drive history: {drives.filter((drive) => drive.companyName === contact.company).length} sample drives · {contact.notes.join("; ") || "No notes yet"}</p><div className="mt-3 flex gap-2"><input value={interaction[contact.id] || ""} onChange={(event) => setInteraction({ ...interaction, [contact.id]: event.target.value })} placeholder="Log a conversation or action" className="min-w-0 flex-1 rounded-lg border border-slate-200 px-3 py-2 text-xs"/><button onClick={() => { const note = interaction[contact.id]?.trim(); if (!note) return; setData((current) => ({ ...current, contacts: current.contacts.map((item) => item.id === contact.id ? { ...item, notes: [note, ...item.notes] } : item) })); record(`Logged employer interaction: ${contact.company}`); setInteraction({ ...interaction, [contact.id]: "" }); }} className="rounded-lg border border-slate-200 px-3 text-xs font-semibold">Log</button></div></article>)}</div></div></section>}

        {panel === "Policies & eligibility" && <section className="grid gap-5 lg:grid-cols-[0.9fr_1.1fr]"><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><ShieldCheck className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Placement policy rules</h3></div><p className="mt-1 text-xs text-slate-500">Configurable rules are saved locally; a production policy engine must enforce them server-side.</p><label className="mt-5 block text-xs font-semibold text-slate-700">Maximum applications per day<input type="number" min="1" max="20" value={data.policies.maxAppsPerDay} onChange={(event) => setData((current) => ({ ...current, policies: { ...current.policies, maxAppsPerDay: Number(event.target.value) } }))} className="mt-1.5 w-full rounded-lg border border-slate-200 p-2.5 text-sm"/></label>{[["noActiveBacklogs", "Block students with active backlogs"], ["blockAfterPlacement", "Block applications after placement"]].map(([key, label]) => <label key={key} className="mt-3 flex items-center justify-between rounded-lg bg-slate-50 p-3 text-xs text-slate-700">{label}<input type="checkbox" checked={data.policies[key as "noActiveBacklogs" | "blockAfterPlacement"]} onChange={(event) => setData((current) => ({ ...current, policies: { ...current.policies, [key]: event.target.checked } }))} className="h-4 w-4 accent-indigo-600"/></label>)}<label className="mt-4 block text-xs font-semibold text-slate-700">Dream offer threshold (LPA)<input type="number" min="0" value={data.policies.dreamThresholdLPA} onChange={(event) => setData((current) => ({ ...current, policies: { ...current.policies, dreamThresholdLPA: Number(event.target.value) } }))} className="mt-1.5 w-full rounded-lg border border-slate-200 p-2.5 text-sm"/></label></div><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><SlidersHorizontal className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Try an eligibility / policy check</h3></div><p className="mt-1 text-xs text-slate-500">This walkthrough explains which configured policy blocks the sample action.</p><div className="mt-4 grid gap-3 sm:grid-cols-2">{[["cgpa", "CGPA"], ["backlogs", "Active backlogs"], ["appsToday", "Applications today"], ["package", "Offer package (LPA), if placed"]].map(([key, label]) => <label key={key} className="text-xs font-medium text-slate-600">{label}<input type="number" value={policyCheck[key as keyof typeof policyCheck] as string} onChange={(event) => setPolicyCheck({ ...policyCheck, [key]: event.target.value })} className="mt-1 block w-full rounded-lg border border-slate-200 p-2.5 text-sm"/></label>)}<label className="flex items-center gap-2 text-xs text-slate-600 sm:col-span-2"><input type="checkbox" checked={policyCheck.placed} onChange={(event) => setPolicyCheck({ ...policyCheck, placed: event.target.checked })}/>Already placed</label></div><div className={`mt-4 rounded-xl p-4 text-sm ${blocked ? "bg-rose-50 text-rose-900" : "bg-emerald-50 text-emerald-900"}`}><p className="font-bold">{blocked ? "Action blocked by configured policy" : "No configured rule blocks this action"}</p><p className="mt-1 text-xs leading-5">{Number(policyCheck.cgpa) < 6 ? "Minimum campus registration CGPA in this sample: 6.0. " : ""}{data.policies.noActiveBacklogs && Number(policyCheck.backlogs) > 0 ? "Active backlogs are not permitted. " : ""}{data.policies.blockAfterPlacement && policyCheck.placed ? "Placed students are blocked by the current rule. " : ""}{Number(policyCheck.appsToday) >= data.policies.maxAppsPerDay ? `Daily application limit (${data.policies.maxAppsPerDay}) reached. ` : ""}{policyCheck.package && Number(policyCheck.package) < data.policies.dreamThresholdLPA ? `Placed package is below the dream threshold (${data.policies.dreamThresholdLPA} LPA).` : ""}</p></div></div></section>}

        {panel === "Interviews & drive day" && <section className="grid gap-5 xl:grid-cols-[0.8fr_1.2fr]"><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><CalendarDays className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Schedule an interview</h3></div><p className="mt-1 text-xs text-slate-500">Room/time conflicts are checked against this browser&apos;s schedule.</p><form onSubmit={addInterview} className="mt-4 space-y-3"><select value={interviewForm.candidate} onChange={(e) => setInterviewForm({ ...interviewForm, candidate: e.target.value })} className="w-full rounded-lg border border-slate-200 p-2.5 text-sm">{students.slice(0, 12).map((student) => <option key={student.id}>{student.name}</option>)}</select><select value={interviewForm.company} onChange={(e) => setInterviewForm({ ...interviewForm, company: e.target.value })} className="w-full rounded-lg border border-slate-200 p-2.5 text-sm">{companies.map((company) => <option key={company.id}>{company.name}</option>)}</select><input value={interviewForm.round} onChange={(e) => setInterviewForm({ ...interviewForm, round: e.target.value })} placeholder="Interview round" className="w-full rounded-lg border border-slate-200 p-2.5 text-sm"/><div className="grid grid-cols-2 gap-2"><input type="date" value={interviewForm.date} onChange={(e) => setInterviewForm({ ...interviewForm, date: e.target.value })} className="rounded-lg border border-slate-200 p-2.5 text-sm"/><input type="time" value={interviewForm.time} onChange={(e) => setInterviewForm({ ...interviewForm, time: e.target.value })} className="rounded-lg border border-slate-200 p-2.5 text-sm"/></div><input value={interviewForm.room} onChange={(e) => setInterviewForm({ ...interviewForm, room: e.target.value })} placeholder="Room / virtual meeting" className="w-full rounded-lg border border-slate-200 p-2.5 text-sm"/>{interviewError && <p role="alert" className="text-xs text-rose-700">{interviewError}</p>}<button className="rounded-lg bg-slate-900 px-4 py-2.5 text-xs font-semibold text-white">Schedule interview</button></form></div><div className="space-y-5"><div className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="font-bold text-slate-900">Interview calendar</h3><p className="mt-1 text-xs text-slate-500">Local schedule · {data.interviews.length} total</p><div className="mt-4 space-y-2">{[...data.interviews].sort((a, b) => `${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`)).map((interview) => <div key={interview.id} className="grid gap-2 rounded-xl bg-slate-50 p-3 text-xs sm:grid-cols-[100px_1fr_auto] sm:items-center"><div className="font-semibold text-indigo-700">{formatDate(interview.date)}<br/>{interview.time}</div><div><p className="font-semibold text-slate-800">{interview.candidate} · {interview.company}</p><p className="text-slate-500">{interview.round} · {interview.room}</p></div><button onClick={() => { setInterviewForm({ ...interview, date: "2026-10-07" }); setData((current) => ({ ...current, interviews: current.interviews.filter((item) => item.id !== interview.id) })); record(`Rescheduled ${interview.candidate}'s interview`); }} className="rounded-lg border border-slate-200 px-2.5 py-1.5 text-[10px] font-semibold">Reschedule</button></div>)}{data.interviews.length === 0 && <p className="rounded-xl bg-slate-50 p-4 text-xs text-slate-500">No interviews scheduled yet.</p>}</div></div><div className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="font-bold text-slate-900">Drive-day check-in queue</h3><p className="mt-1 text-xs text-slate-500">Demo attendance for candidates in the sample application roster.</p><div className="mt-3 space-y-2">{applications.slice(0, 5).map((application) => <label key={application.id} className="flex items-center justify-between rounded-lg border border-slate-100 p-3 text-xs"><span><b>{application.studentName}</b><span className="ml-2 text-slate-500">{application.companyName} · {application.status}</span></span><span className="flex items-center gap-2"><span className={data.checkedIn.includes(application.id) ? "text-emerald-700" : "text-slate-400"}>{data.checkedIn.includes(application.id) ? "Checked in" : "Waiting"}</span><input type="checkbox" checked={data.checkedIn.includes(application.id)} onChange={(event) => { setData((current) => ({ ...current, checkedIn: event.target.checked ? [...current.checkedIn, application.id] : current.checkedIn.filter((id) => id !== application.id) })); record(`${event.target.checked ? "Checked in" : "Reverted check-in for"} ${application.studentName}`); }} className="h-4 w-4 accent-emerald-600"/></span></label>)}</div></div></div></section>}

        {panel === "Assessments & offers" && <section className="grid gap-5 xl:grid-cols-[0.85fr_1.15fr]"><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><ClipboardCheck className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Assessment builder</h3></div><p className="mt-1 text-xs text-slate-500">Create and publish an assessment outline; question delivery and secure grading need a server.</p><form onSubmit={createAssessment} className="mt-4 space-y-3"><input required value={assessmentForm.title} onChange={(e) => setAssessmentForm({ ...assessmentForm, title: e.target.value })} placeholder="Assessment name" className="w-full rounded-lg border border-slate-200 p-2.5 text-sm"/><select value={assessmentForm.type} onChange={(e) => setAssessmentForm({ ...assessmentForm, type: e.target.value })} className="w-full rounded-lg border border-slate-200 p-2.5 text-sm">{["Aptitude", "Logical reasoning", "Technical MCQ", "DSA coding", "SQL", "Communication"].map((type) => <option key={type}>{type}</option>)}</select><div className="grid grid-cols-2 gap-2"><label className="text-xs text-slate-500">Minutes<input type="number" min="5" value={assessmentForm.duration} onChange={(e) => setAssessmentForm({ ...assessmentForm, duration: Number(e.target.value) })} className="mt-1 w-full rounded-lg border border-slate-200 p-2.5 text-sm"/></label><label className="text-xs text-slate-500">Questions<input type="number" min="1" value={assessmentForm.questions} onChange={(e) => setAssessmentForm({ ...assessmentForm, questions: Number(e.target.value) })} className="mt-1 w-full rounded-lg border border-slate-200 p-2.5 text-sm"/></label></div><button className="rounded-lg bg-slate-900 px-4 py-2.5 text-xs font-semibold text-white">Save assessment draft</button></form><div className="mt-4 space-y-2">{data.assessments.map((assessment) => <div key={assessment.id} className="flex items-center justify-between gap-2 rounded-lg bg-slate-50 p-3 text-xs"><div><b>{assessment.title}</b><p className="text-slate-500">{assessment.type} · {assessment.questions} questions · {assessment.duration} min</p></div><button onClick={() => { setData((current) => ({ ...current, assessments: current.assessments.map((item) => item.id === assessment.id ? { ...item, status: item.status === "Draft" ? "Published" : "Draft" } : item) })); record(`Toggled assessment ${assessment.title}`); }} className="rounded bg-white px-2 py-1 font-semibold">{assessment.status}</button></div>)}</div></div><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><CheckCircle2 className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Offer lifecycle</h3></div><p className="mt-1 text-xs text-slate-500">Move the sample offer through its local lifecycle and record each change.</p><div className="mt-4 space-y-3">{data.offers.map((offer) => <article key={offer.id} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-sm font-semibold text-slate-900">{offer.student}</p><p className="text-xs text-slate-500">{offer.company} · {offer.role} · ₹{offer.packageLPA} LPA</p></div><span className="rounded-full bg-emerald-50 px-2.5 py-1 text-[10px] font-semibold text-emerald-800">{offer.status}</span></div><div className="mt-3 flex flex-wrap items-center gap-1.5">{(["Draft", "Released", "Viewed", "Accepted", "Rejected", "Joined"] as Offer["status"][]).map((status) => <button key={status} onClick={() => updateOffer(offer.id, status)} className={`rounded-md px-2 py-1.5 text-[10px] font-semibold ${offer.status === status ? "bg-indigo-600 text-white" : "bg-slate-100 text-slate-600 hover:bg-slate-200"}`}>{status}</button>)}</div><p className="mt-2 text-[10px] text-slate-400">Acceptance deadline: {formatDate(offer.deadline)} · Offer documents are not stored here.</p></article>)}</div></div></section>}

        {panel === "Reports & data" && <section className="grid gap-5 xl:grid-cols-2"><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><FileSpreadsheet className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Download placement reports</h3></div><p className="mt-1 text-xs text-slate-500">Export currently loaded sample records to CSV.</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><button onClick={() => csvDownload("placement-applications.csv", [["student", "rollNumber", "branch", "company", "role", "status"], ...applications.map((item) => [item.studentName, item.studentRollNumber, item.studentBranch, item.companyName, item.driveName, item.status])])} className="rounded-xl border border-slate-200 p-4 text-left hover:bg-slate-50"><b className="text-xs">Applications report</b><p className="mt-1 text-[10px] text-slate-500">Candidate pipeline roster</p></button><button onClick={() => csvDownload("placement-drives.csv", [["company", "role", "deadline", "packageLPA", "status"], ...drives.map((item) => [item.companyName, item.role, item.applicationDeadline, String(item.packageLPA ?? ""), item.status])])} className="rounded-xl border border-slate-200 p-4 text-left hover:bg-slate-50"><b className="text-xs">Drive report</b><p className="mt-1 text-[10px] text-slate-500">Companies and drive criteria</p></button><button onClick={() => csvDownload("student-roster.csv", [["name", "rollNumber", "email", "branch", "cgpa"], ...students.map((item) => [item.name, item.rollNumber, item.email, item.branch, String(item.cgpa)])])} className="rounded-xl border border-slate-200 p-4 text-left hover:bg-slate-50"><b className="text-xs">Student roster</b><p className="mt-1 text-[10px] text-slate-500">Loaded sample records</p></button><button onClick={() => csvDownload("company-summary.csv", [["company", "industry", "sampleDrives"], ...companies.map((company) => [company.name, company.industry, String(drives.filter((drive) => drive.companyId === company.id).length)])])} className="rounded-xl border border-slate-200 p-4 text-left hover:bg-slate-50"><b className="text-xs">Company summary</b><p className="mt-1 text-[10px] text-slate-500">Internal drive history only</p></button></div></div><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><Download className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Import student CSV</h3></div><p className="mt-1 text-xs leading-5 text-slate-500">Required columns: name, rollNumber, email, branch, cgpa. Upload accepts valid rows into this browser only; it does not modify the canonical student directory.</p><label className="mt-4 flex cursor-pointer items-center justify-center gap-2 rounded-xl border-2 border-dashed border-slate-200 p-6 text-xs font-semibold text-slate-600 hover:bg-slate-50"><Download className="h-4 w-4"/>Choose CSV<input type="file" accept=".csv,text/csv" className="sr-only" onChange={(event) => void importStudents(event.target.files?.[0])}/></label>{fileError && <p aria-live="polite" className="mt-3 rounded-lg bg-indigo-50 p-3 text-xs text-indigo-900">{fileError}</p>}{data.importRows.length > 0 && <p className="mt-3 text-xs text-emerald-700">{data.importRows.length} imported roster rows loaded.</p>}</div></section>}

        {panel === "Communications & audit" && <section className="grid gap-5 xl:grid-cols-[0.8fr_1.2fr]"><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><Mail className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Communication center</h3></div><p className="mt-1 text-xs text-slate-500">Draft and preview announcements. No email, SMS, or push message is sent.</p><form onSubmit={sendBroadcast} className="mt-4 space-y-3"><input required value={broadcastForm.title} onChange={(e) => setBroadcastForm({ ...broadcastForm, title: e.target.value })} placeholder="Announcement title" className="w-full rounded-lg border border-slate-200 p-2.5 text-sm"/><select value={broadcastForm.audience} onChange={(e) => setBroadcastForm({ ...broadcastForm, audience: e.target.value })} className="w-full rounded-lg border border-slate-200 p-2.5 text-sm">{["All final-year students", "CSE students", "IT students", "Eligible for selected drive"].map((audience) => <option key={audience}>{audience}</option>)}</select><button className="rounded-lg bg-slate-900 px-4 py-2.5 text-xs font-semibold text-white">Save announcement draft</button></form><div className="mt-4 space-y-2">{data.communications.map((item, index) => <div key={`${item.title}-${index}`} className="rounded-lg bg-slate-50 p-3 text-xs"><b>{item.title}</b><p className="mt-1 text-slate-500">{item.audience} · Saved {new Date(item.date).toLocaleString()}</p></div>)}</div></div><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><Activity className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Audit trail</h3></div><p className="mt-1 text-xs text-slate-500">Browser-local event log for actions in this operations workspace.</p><div className="mt-4 max-h-[480px] space-y-2 overflow-y-auto">{data.audit.map((item, index) => <div key={`${item.at}-${index}`} className="flex gap-3 rounded-lg border border-slate-100 p-3"><span className="mt-0.5 h-2 w-2 shrink-0 rounded-full bg-indigo-500"/><div><p className="text-xs font-medium text-slate-700">{item.action}</p><p className="mt-1 text-[10px] text-slate-400">{new Date(item.at).toLocaleString()}</p></div></div>)}{data.audit.length === 0 && <p className="rounded-xl bg-slate-50 p-4 text-xs text-slate-500">Actions you take here will appear in this log.</p>}</div></div></section>}

        {panel === "Drive analyzer" && <section className="grid gap-5 xl:grid-cols-[0.85fr_1.15fr]"><div className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><Activity className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Drive performance snapshot</h3></div><p className="mt-1 text-xs leading-5 text-slate-500">Counts current application statuses and eligibility from sample records. Historical stage timestamps are not available, so this view does not claim a conversion rate or causal drop-off.</p><label className="mt-4 block text-xs font-semibold text-slate-600">Choose drive<select value={analysisDriveId} onChange={(event) => setAnalysisDriveId(event.target.value)} className="mt-1.5 w-full rounded-lg border border-slate-200 p-2.5 text-sm font-normal">{drives.map((drive) => <option key={drive.id} value={drive.id}>{drive.companyName} · {drive.role}</option>)}</select></label>{(() => { const drive = drives.find((item) => item.id === analysisDriveId); if (!drive) return null; const candidates = effectiveApplications.filter((application) => application.driveId === drive.id); const eligibleCount = students.filter((student) => drive.eligibility.branches.includes(student.branch) && student.cgpa >= drive.eligibility.minCGPA && student.backlogs <= drive.eligibility.maxBacklogs && (!drive.eligibility.tenthMin || student.tenthPercent >= drive.eligibility.tenthMin) && (!drive.eligibility.twelfthMin || student.twelfthPercent >= drive.eligibility.twelfthMin)).length; const statusCounts = ["Not Responded", "Confirmed", "Shortlisted", "Assessment", "Interview", "Selected", "Placed", "Rejected"]; return <><div className="mt-4 rounded-xl bg-slate-50 p-4"><p className="text-sm font-semibold text-slate-900">{drive.companyName} · {drive.role}</p><div className="mt-3 grid grid-cols-2 gap-3 text-xs"><div><span className="text-slate-500">Eligible sample students</span><b className="mt-1 block text-lg text-slate-900">{eligibleCount}</b></div><div><span className="text-slate-500">Application records</span><b className="mt-1 block text-lg text-slate-900">{candidates.length}</b></div></div></div><p className="mt-4 text-xs font-semibold text-slate-800">Current status distribution</p><div className="mt-2 space-y-2">{statusCounts.map((status) => { const count = candidates.filter((candidate) => candidate.status === status).length; return <div key={status} className="flex items-center gap-2 text-[10px]"><span className="w-24 text-slate-600">{status}</span><div className="h-1.5 flex-1 rounded-full bg-slate-100"><div className="h-1.5 rounded-full bg-indigo-500" style={{ width: `${candidates.length ? count / candidates.length * 100 : 0}%` }}/></div><b className="w-5 text-right text-slate-800">{count}</b></div>; })}</div></>; })()}</div><div className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="font-bold text-slate-900">Evidence and next checks</h3><p className="mt-1 text-xs text-slate-500">Read from currently loaded company, student, and application sample records.</p><div className="mt-4 space-y-3">{(() => { const drive = drives.find((item) => item.id === analysisDriveId); const candidates = effectiveApplications.filter((application) => application.driveId === analysisDriveId); const notResponded = candidates.filter((application) => application.status === "Not Responded").length; const assessmentOrBeyond = candidates.filter((application) => ["Assessment", "Interview", "Selected", "Placed"].includes(application.status)).length; const selected = candidates.filter((application) => ["Selected", "Placed"].includes(application.status)).length; return [
          { title: `${notResponded} candidate records need confirmation`, body: notResponded ? "Review the pending roster and follow up through your approved communication channel." : "No application records are currently marked Not Responded." },
          { title: `${assessmentOrBeyond} records reached assessment or later`, body: "Use the candidate stage history and interviewer feedback to understand individual progress." },
          { title: `${selected} records are selected or placed`, body: drive ? `The drive lists ${drive.openings} openings. Check offer acceptance and joining records before publishing outcomes.` : "Check offer acceptance and joining records before publishing outcomes." },
        ].map((insight) => <div key={insight.title} className="rounded-xl border border-slate-100 p-4"><p className="text-sm font-semibold text-slate-800">{insight.title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{insight.body}</p></div>); })()}</div><p className="mt-4 text-[10px] leading-4 text-slate-400">These are descriptive checks, not an AI-generated analysis. Status counts are snapshot records, not reconstructed event funnels.</p></div></section>}

        {panel === "Employer discovery" && <section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><div className="flex items-center gap-2"><Building2 className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">Employer discovery</h3></div><p className="mt-1 text-xs text-slate-500">Recommendations use only internal sample history. No live hiring signal is available.</p></div><label className="relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400"/><input value={filter} onChange={(event) => setFilter(event.target.value)} placeholder="Search by company or industry" className="rounded-lg border border-slate-200 py-2 pl-9 pr-3 text-xs"/></label></div><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{companies.filter((company) => `${company.name} ${company.industry}`.toLowerCase().includes(filter.toLowerCase())).map((company) => { const history = drives.filter((drive) => drive.companyId === company.id); const hires = applications.filter((application) => application.companyId === company.id && ["Selected", "Placed"].includes(application.status)).length; return <article key={company.id} className="rounded-xl border border-slate-100 p-4"><div className="flex items-center gap-2"><span className="flex h-8 w-8 items-center justify-center rounded-lg text-xs font-bold text-white" style={{ backgroundColor: company.logoColor }}>{company.name.slice(0, 2).toUpperCase()}</span><div><b className="text-sm text-slate-900">{company.name}</b><p className="text-[10px] text-slate-500">{company.industry}</p></div></div><p className="mt-3 text-xs leading-5 text-slate-600">Recommended because {history.length ? `the college has ${history.length} recorded drive${history.length === 1 ? "" : "s"} and ${hires} sample selection${hires === 1 ? "" : "s"}.` : "the sample database includes this company; no campus hiring history is recorded yet."}</p><p className="mt-2 text-[10px] text-slate-400">Roles: {history.length ? [...new Set(history.map((drive) => drive.role))].join(", ") : "No recorded role"} · Source: local sample history</p><button onClick={() => { setPanel("Employer CRM"); setContactForm({ ...contactForm, company: company.name }); }} className="mt-3 rounded-lg bg-slate-900 px-3 py-2 text-[10px] font-semibold text-white">Add recruiter contact</button></article>; })}</div></section>}

        {panel === "TPO insight assistant" && <section className="grid gap-5 lg:grid-cols-[1fr_300px]"><div className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-center gap-2"><Activity className="h-5 w-5 text-indigo-600"/><h3 className="font-bold text-slate-900">TPO insight assistant preview</h3></div><p className="mt-1 text-xs leading-5 text-slate-500">Local, rule-based answers using the sample roster and browser-updated candidate stages. It does not execute actions or call an AI service.</p><textarea value={copilotPrompt} onChange={(event) => setCopilotPrompt(event.target.value)} rows={3} placeholder="Ask about eligible students, pending confirmations, funnel counts, or a recruiter follow-up" className="mt-4 w-full rounded-lg border border-slate-200 p-3 text-sm"/><button onClick={askTpoAssistant} disabled={!copilotPrompt.trim()} className="mt-3 rounded-lg bg-indigo-600 px-4 py-2.5 text-xs font-semibold text-white disabled:opacity-40">Get a data-backed preview</button>{copilotAnswer && <div aria-live="polite" className="mt-4 rounded-xl border border-indigo-100 bg-indigo-50 p-4 text-sm leading-6 text-indigo-950">{copilotAnswer}</div>}</div><div className="rounded-2xl border border-slate-200 bg-white p-5"><h3 className="font-bold text-slate-900">Suggested questions</h3>{["Show CSE students with CGPA above 8", "Who has not confirmed participation?", "Summarize the placement funnel", "Draft an email to a recruiter"].map((question) => <button key={question} onClick={() => setCopilotPrompt(question)} className="mt-3 block w-full rounded-lg border border-slate-200 p-3 text-left text-xs text-slate-600 hover:bg-slate-50">{question}</button>)}<p className="mt-4 text-[10px] leading-4 text-slate-400">Production AI needs a protected service, structured data access, access checks, and human approval for actions.</p></div></section>}
        {!ready && <span className="sr-only" aria-live="polite">Loading saved operations data</span>}
      </div>
    </div>
  );
}
